/* Achei & Postei — controles de apresentação, sem alterações nos serviços.
   Os módulos existentes continuam responsáveis pelo login e pelos dados.
   ?preview=1 ativa apenas a amostra visual, sem acessar sua conta. */
(() => {
 'use strict';
 const init = () => {
  const $ = (s) => document.querySelector(s);
  const $$ = (s) => [...document.querySelectorAll(s)];
  const preview = new URLSearchParams(location.search).get('preview') === '1';
  const showTab = (tab) => {
   $$('.tab-panel').forEach(p => p.classList.toggle('hidden', p.id !== 'tab-' + tab));
   $$('.nav-item').forEach(b => { const active = b.dataset.tab === tab; b.classList.toggle('active', active); b.setAttribute('aria-current', active ? 'page' : 'false'); });
  };
  const showSubtab = (tab) => {
   $$('.subtab-panel').forEach(p => p.classList.toggle('hidden', p.id !== 'subtab-' + tab));
   $$('.subtab-btn').forEach(b => { const active = b.dataset.subtab === tab; b.classList.toggle('active',active); b.setAttribute('aria-selected', String(active)); });
  };
  // Run after the original modules' click handlers, preserving their data loads.
  document.addEventListener('click', event => {
   const target = event.target instanceof Element ? event.target : null;
   if (!target) return;
   const nav = target.closest('.nav-item');
   if (nav) queueMicrotask(() => showTab(nav.dataset.tab));
   const sub = target.closest('.subtab-btn');
   if (sub) showSubtab(sub.dataset.subtab);
   if (target.closest('[data-new-automation], [data-open-new-automation]')) {
    $('[data-tab="dashboard"]')?.click();
    $('[data-subtab="new"]')?.click();
   }
   if (target.closest('[data-close-sheet]')) $('[data-subtab="list"]')?.click();
   const seg = target.closest('.seg-btn');
   if (seg) {
    const parent = seg.closest('.tab-panel');
    parent?.querySelectorAll('.seg-panel').forEach(p => p.classList.toggle('hidden', p.id !== seg.dataset.seg));
    seg.parentElement?.querySelectorAll('.seg-btn').forEach(b => b.classList.toggle('active',b === seg));
   }
   if (target.closest('[data-nav-collapse]')) {
    document.body.classList.toggle('nav-is-collapsed');
    const button = $('[data-nav-collapse]');
    const collapsed = document.body.classList.contains('nav-is-collapsed');
    button?.setAttribute('aria-label', collapsed ? 'Expandir menu' : 'Recolher menu');
    button?.setAttribute('title', collapsed ? 'Expandir menu' : 'Recolher menu');
   }
  });
  const email = $('#authEmail');
  const password = $('#authPassword');
  [email,password].forEach(input => input?.addEventListener('keydown',e => { if (e.key === 'Enter') $('#authSubmitBtn')?.click(); }));
  // Dialog keyboard and focus behavior, including dialogs injected by modules.
  let returnFocus = null;
  const visibleDialog = () => $$('.modal-overlay').find(m => !m.classList.contains('hidden'));
  const observer = new MutationObserver(() => {
   const dialog = visibleDialog();
   document.body.classList.toggle('dialog-open',Boolean(dialog));
   if (dialog && !dialog.contains(document.activeElement)) { returnFocus = document.activeElement; dialog.querySelector('input:not([type="hidden"]),button')?.focus(); }
   else if (!dialog && returnFocus instanceof HTMLElement) { returnFocus.focus(); returnFocus = null; }
  });
  observer.observe(document.body,{subtree:true,attributes:true,attributeFilter:['class'],childList:true});
  document.addEventListener('keydown',e => {
   const dialog = visibleDialog();
   if (!dialog) return;
   if (e.key === 'Escape') { dialog.querySelector('.modal-close')?.click(); }
   if (e.key === 'Tab') {
    const items = [...dialog.querySelectorAll('button:not(:disabled),input:not([type="hidden"]),a[href],select,textarea')];
    const first = items[0], last = items[items.length - 1];
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last?.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first?.focus(); }
   }
  });
  if (!preview) return;
  document.documentElement.removeAttribute('data-theme');
  $('#authScreen')?.classList.add('hidden');
  $('#appScreen')?.classList.remove('hidden');
  $('#userAvatar').textContent = 'WR';
  $('#userEmailLabel').textContent = 'Meu perfil';
  showTab('dashboard'); showSubtab('list');
  $('#kpiTotal').textContent = '12'; $('#kpiAtivas').textContent = '10'; $('#kpiPausadas').textContent = '2';
  const details = ['<span class="positive">+3</span> neste mês','Respondendo por você','Prontas para reativar'];
  $$('#tab-dashboard .kpi-item').forEach((el,i) => { const p = document.createElement('span'); p.className='kpi-detail'; p.innerHTML=details[i]; el.appendChild(p); });
  // Images are embedded to keep the requested delivery at exactly three files.
  const image = 'data:image/jpeg;base64,';
  const samples = [
   {title:'Tênis Runner Pro', account:'@achadinhos.da.we', keyword:'QUERO', count:'248', active:true, name:'Tênis Runner Pro'},
   {title:'Fone Bluetooth', account:'@achadinhos.da.we', keyword:'FONE', count:'186', active:true, name:'Fone Bluetooth Premium'},
   {title:'Bolsa Everyday', account:'@estilo.e.achados', keyword:'BOLSA', count:'94', active:false, name:'Bolsa Everyday'}
  ];
  const card = (item,i) => `<article class="automation-card" data-preview-name="${item.title.toLowerCase()}"><div class="preview-product product-${i+1}"><img src="${image}" alt="${item.name}" width="1536" height="512"><span class="badge ${item.active?'badge-ativo':'badge-muted'}">${item.active?'Ativa':'Pausada'}</span></div><div class="preview-card-body"><h3>${item.title}</h3><p>${item.account} · Publicação do Instagram</p><div class="preview-card-line"><span>Palavra-chave</span><span class="keyword-chip">${item.keyword}</span></div><div class="preview-card-line"><span>Destino</span><strong>↗ Link do produto</strong></div><div class="preview-card-line"><span>Directs enviados</span><strong>↗ ${item.count}</strong></div></div><div class="preview-card-footer"><label class="card-toggle"><input type="checkbox" ${item.active?'checked':''} aria-label="Ativar ${item.title}"><i></i><span>${item.active?'Ativa':'Pausada'}</span></label><div class="automation-card-actions"><button type="button" class="icon-btn" data-preview-edit="${i}" aria-label="Editar ${item.title}" title="Editar automação">✎</button></div></div></article>`;
  $('#automationsTableBody').innerHTML=samples.map(card).join('');
  const note=document.createElement('p'); note.className='preview-notice'; note.textContent='Prévia da interface · Dados ilustrativos'; $('#subtab-list').appendChild(note);
  $('#automationSearch')?.addEventListener('input',e => { const term=e.target.value.toLowerCase(); $$('#automationsTableBody .automation-card').forEach(c => c.classList.toggle('hidden',!c.textContent.toLowerCase().includes(term))); });
  document.addEventListener('change',e => { if (e.target.matches('.card-toggle input')) { const active=e.target.checked, card=e.target.closest('.automation-card'); card.querySelector('.badge').className='badge '+(active?'badge-ativo':'badge-muted'); card.querySelector('.badge').textContent=active?'Ativa':'Pausada'; card.querySelector('.card-toggle span').textContent=active?'Ativa':'Pausada'; const on=$$('.card-toggle input:checked').length; $('#kpiAtivas').textContent=String(7+on); $('#kpiPausadas').textContent=String(3-on); } });
  $('#automationIgAccount').innerHTML='<option>@achadinhos.da.we</option><option>@estilo.e.achados</option>';
  let editing = null;
  document.addEventListener('click',e => { const button=e.target.closest('[data-preview-edit]'); if (!button) return; editing=Number(button.dataset.previewEdit); const item=samples[editing]; $('#instagramMediaId').value='https://www.instagram.com/p/exemplo/'; $('#palavraChave').value=item.keyword; $('#produtoUrl').value='https://exemplo.com/produto'; $('#tituloProduto').value=item.title; showSubtab('new'); });
  $('#saveAutomationBtn').addEventListener('click',()=> { const keyword=$('#palavraChave').value.trim(), link=$('#produtoUrl').value.trim(), post=$('#instagramMediaId').value.trim(); if (!post || !keyword || !/^https?:\/\//.test(link)) { $('#statusBanner').className='banner error'; $('#statusBanner').textContent='Preencha o post, a palavra-chave e um link válido para visualizar a automação.'; return; } const item={title:$('#tituloProduto').value.trim() || 'Nova automação', account:'@achadinhos.da.we',keyword,count:'0',active:true,name:'Produto'}; if (editing !== null) { samples[editing]=item; editing=null; } else samples.push(item); $('#automationsTableBody').innerHTML=samples.map((s,i)=>card(s,i%3)).join(''); showSubtab('list'); $('#statusBanner').className='banner success'; $('#statusBanner').textContent='Amostra atualizada nesta prévia. Nenhuma automação real foi criada.'; });
  $$('input[name="triggerMode"]').forEach(r=>r.addEventListener('change',()=>$('#palavraChaveField').classList.toggle('hidden',r.checked && r.value==='any')));
  $('#toggleImagemUrlBtn').addEventListener('click',()=>$('#imagemUrlField').classList.toggle('hidden'));
  const showModal = (id) => $('#'+id)?.classList.remove('hidden');
  const hideModal = (id) => $('#'+id)?.classList.add('hidden');
  $('#newProdutoBtn').addEventListener('click',()=>showModal('produtoModal'));
  $('#pickProdutoBtn').addEventListener('click',()=>showModal('produtoPickerModal'));
  ['closeProdutoModalBtn','cancelProdutoModalBtn'].forEach(id=>$('#'+id)?.addEventListener('click',()=>hideModal('produtoModal')));
  $('#closeProdutoPickerBtn').addEventListener('click',()=>hideModal('produtoPickerModal'));
  $('#saveProdutoBtn').addEventListener('click',()=> { $('#produtoModalError').textContent='Esta é uma prévia visual. O cadastro real continua no seu sistema atual.'; $('#produtoModalError').classList.remove('hidden'); });
  $('#latestPostsGrid').innerHTML=samples.slice(0,3).map((s,i)=>`<article class="latest-post-card"><div class="preview-product product-${i+1}"><img src="${image}" alt="${s.name}" width="1536" height="512"></div><div class="latest-post-info"><strong>${s.account}</strong><p>${s.title}</p></div><div class="latest-post-actions"><button type="button" class="btn btn-outline btn-sm" data-new-automation>Criar automação</button></div></article>`).join('');
  $('#produtosGrid').innerHTML='<div class="empty-state">Seu catálogo de produtos aparecerá aqui.</div>';
  $('#produtoPickerList').innerHTML='<div class="empty-state">Nenhum produto nesta prévia.</div>';
  $('#igLoadingStatus').classList.add('hidden'); $('#igAccountsList').classList.remove('hidden');
  $('#igAccountsList').innerHTML=samples.slice(0,2).map(s=>`<div class="ig-status-row"><span class="ig-dot"></span><div class="ig-status-text"><strong>${s.account}</strong><p>Conta comercial do Instagram</p></div><span class="badge badge-ativo">Conectada</span></div>`).join('');
  $('#igTesterForm').addEventListener('submit',e=> { e.preventDefault(); $('#igTesterFormError').textContent='A conexão real está disponível no seu sistema atual; esta tela é apenas uma prévia.'; $('#igTesterFormError').classList.remove('hidden'); });
  $('#logoutBtn').addEventListener('click',()=> { $('#appScreen').classList.add('hidden'); $('#authScreen').classList.remove('hidden'); });
  $('#authSubmitBtn').addEventListener('click',()=> { $('#authBanner').className='banner error'; $('#authBanner').textContent='O login real depende dos scripts e serviços da sua plataforma atual.'; });
  $('#ovKpis').innerHTML='<div class="kpi-item"><span class="kpi-label">Directs enviados</span><b class="kpi-value">528</b></div><div class="kpi-item"><span class="kpi-label">Taxa de sucesso</span><b class="kpi-value">98,6%</b></div><div class="kpi-item"><span class="kpi-label">Automações ativas</span><b class="kpi-value">10</b></div>';
  $('#ovDaily').innerHTML='<div class="overview-bars">'+[30,45,35,70,60,85,68,90,73,95,82,100].map(h=>`<i style="--bar-height:${h}%"></i>`).join('')+'</div><p class="preview-notice">Dados ilustrativos</p>';
  ['ovPosts','ovFormats','ovHours','ovAccounts','ovErrors'].forEach(id=>$('#'+id).innerHTML='<div class="empty-state">Os resultados reais aparecerão aqui.</div>');
  $$('.range-btn').forEach(b=>b.addEventListener('click',()=>$$('.range-btn').forEach(x=>x.classList.toggle('active',x===b))));
 };
 if (document.readyState==='loading') document.addEventListener('DOMContentLoaded',init,{once:true}); else init();
})();
